package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="spms_monitoring_action",uniqueConstraints=@UniqueConstraint(name="uk_spms_monitoring_action_request",columnNames={"agency_id","monitoring_case_id","request_key"}))public class PerformanceMonitoringAction extends RspAuditedEntity{@Column(name="monitoring_case_id",nullable=false,length=36)private String monitoringCaseId;@Column(name="subject_id",length=36)private String subjectId;@Column(name="action_type",nullable=false,length=40)private String actionType;@Column(name="request_key",nullable=false,length=100)private String requestKey;@Column(name="actor_employee_no",nullable=false,length=100)private String actorEmployeeNo;@Column(name="action_reason",length=2000)private String actionReason;@Column(name="acted_at",nullable=false)private Instant actedAt;protected PerformanceMonitoringAction(){}public PerformanceMonitoringAction(String a,String c,String subject,String type,String key,String actor,String reason,Instant at){super(a);monitoringCaseId=requiredText(c,"monitoringCaseId");subjectId=optionalText(subject);actionType=requiredText(type,"actionType");requestKey=requiredText(key,"requestKey");actorEmployeeNo=requiredText(actor,"actorEmployeeNo");actionReason=optionalText(reason);actedAt=at;}public String getMonitoringCaseId(){return monitoringCaseId;}public String getSubjectId(){return subjectId;}public String getActionType(){return actionType;}public String getRequestKey(){return requestKey;}public String getActorEmployeeNo(){return actorEmployeeNo;}public String getActionReason(){return actionReason;}public Instant getActedAt(){return actedAt;}}
